111: const selected = Object.fromEntries(Object.keys(options).map(key => [key, 0]));
112: let activeStep = 0;
113: let bladeIgnited = false;
114: let bladeUserChoice = null;
115: const $ = (id) => document.getElementById(id);
116: function syncBladeToggle() {
117:   const toggle = $('bladeToggle');
118:   toggle.setAttribute('aria-checked', String(bladeIgnited));
119:   toggle.setAttribute('aria-label', `${bladeIgnited ? 'Turn preview blade off' : 'Turn preview blade on'}`);
120:   toggle.classList.toggle('is-on', bladeIgnited);
121:   toggle.querySelector('.blade-power-state').textContent = bladeIgnited ? 'ON' : 'OFF';
122: }
123: const money = (amount) => `¤ ${Math.round(amount).toLocaleString('en-US')}`;
124: 
125: function selectedOption(id) { return options[id][selected[id]]; }
126: function totalValue() {
127:   const sum = Object.keys(options).reduce((total, key) => total + selectedOption(key).price, 0);
128:   const rarity = Object.values(selected).filter(index => index > 0).length >= 5 ? 360 : 0;
129:   const material = selected.hilt === 3 && selected.pommel === 3 ? 140 : 0;
130:   const harmony = selected.emitter === selected.crystal % 4 ? 160 : 0;
131:   return sum + rarity + material + harmony;
132: }
133: function buildName() {
134:   const hilt = selectedOption('hilt').name;
135:   const crystal = selectedOption('crystal').name;
136:   return `${crystal} ${hilt}`;
137: }
138: function renderSteps() {
139:   $('stepList').innerHTML = steps.map((step, index) => `<button class="step-item ${index === activeStep ? 'active' : ''} ${index < activeStep ? 'done' : ''}" data-step="${index}" aria-current="${index === activeStep ? 'step' : 'false'}"><span class="step-index">${index < activeStep ? '✓' : `0${index + 1}`}</span><span class="step-copy"><strong>${step.title}</strong><small>${step.kicker}</small></span>${index === activeStep ? '<span class="step-state">↗</span>' : ''}</button>`).join('');
140:   document.querySelectorAll('.step-item').forEach(button => button.addEventListener('click', () => setStep(Number(button.dataset.step))));
141:   $('progressFill').style.width = `${((activeStep + 1) / steps.length) * 100}%`;
142:   const stepCount = String(steps.length).padStart(2, '0');
143:   document.querySelector('.build-number').innerHTML = `${String(activeStep + 1).padStart(2, '0')}<br><span>/ ${stepCount}</span>`;
144:   $('stepSummary').innerHTML = `${String(activeStep + 1).padStart(2, '0')} / ${stepCount} &nbsp; ${steps[activeStep].title.toUpperCase()}`;
145:   document.querySelector('.scene-label-right').textContent = `${String(activeStep + 1).padStart(2, '0')} — ${stepCount}`;
146:   $('prevStep').disabled = activeStep === 0;
147:   const isLast = activeStep === steps.length - 1;
148:   $('nextStep').innerHTML = isLast ? 'SELL SABER <span>↗</span>' : 'NEXT PART <span>→</span>';
149:   $('finishButton').innerHTML = isLast ? 'FINISH & SELL <span>↗</span>' : 'NEXT PART <span>→</span>';
150: }
151: function renderOptions() {
152:   const step = steps[activeStep];
153:   const list = options[step.id];
154:   $('categoryEyebrow').textContent = step.eyebrow;
155:   $('categoryTitle').textContent = step.heading;
156:   $('categoryDescription').textContent = step.description;
157:   $('componentCount').innerHTML = `${String(selected[step.id] + 1).padStart(2, '0')} <i>/ ${String(list.length).padStart(2, '0')}</i>`;
158:   $('optionList').innerHTML = list.map((option, index) => {
159:     const swatch = option.swatch === undefined ? (step.id === 'crystal' ? 'crystal' : option.style === 'ribs' || option.style === 'crown' ? 'ridged' : '') : option.swatch;
160:     const swatchStyle = option.color ? ` style="--crystal:${option.color};background:radial-gradient(circle,${option.color} 0,#384a5c 32%,#202623 72%)"` : '';
161:     const title = step.id === 'crystal' ? `Kyber · ${option.name}` : option.name;
162:     return `<button class="option-card ${selected[step.id] === index ? 'selected' : ''}" data-option="${index}" aria-pressed="${selected[step.id] === index}"><span class="option-swatch ${swatch}"${swatchStyle}></span><span class="option-copy"><strong>${title}</strong><small>${option.detail}</small></span><span class="option-price">${money(option.price)}</span></button>`;
163:   }).join('');
164:   document.querySelectorAll('.option-card').forEach(button => button.addEventListener('click', () => {
165:     selected[step.id] = Number(button.dataset.option);
166:     if (step.id === 'crystal' || step.id === 'blade') bladeIgnited = true;
167:     syncBladeToggle();
168:     renderOptions(); updateUI(); rebuildSaber(); playTone(480 + activeStep * 70, .07);
169:   }));
170:   $('selectionNote').textContent = selectedOption(step.id).note;
171:   $('partValue').textContent = money(selectedOption(step.id).price);
172: }
173: function setStep(index) {
174:   activeStep = Math.max(0, Math.min(steps.length - 1, index));
175:   if (steps[activeStep].id !== 'crystal' && steps[activeStep].id !== 'blade') {
176:     bladeIgnited = bladeUserChoice === true;
177:     syncBladeToggle();
178:     rebuildSaber();
179:   }
180:   renderSteps(); renderOptions();
181: }
182: function updateUI() {
183:   const crystal = selectedOption('crystal');
184:   $('previewName').textContent = buildName();
185:   $('crystalReadout').textContent = `KYBER · ${crystal.name.toUpperCase()}`;
186:   $('crystalDot').style.background = crystal.color;
187:   $('crystalDot').style.color = crystal.color;
188:   $('crystalDot').style.boxShadow = `0 0 11px ${crystal.color}99`;
189:   $('previewPrice').textContent = money(totalValue());
190: }
191: function nextStep() {
192:   if (activeStep < steps.length - 1) { setStep(activeStep + 1); playTone(370, .09); }
193:   else openSale();
194: }
195: $('prevStep').addEventListener('click', () => setStep(activeStep - 1));
196: $('nextStep').addEventListener('click', nextStep);
197: $('finishButton').addEventListener('click', nextStep);
198: 
199: let audioContext = null;
200: let soundOn = false;
201: function playTone(frequency, duration) {
202:   if (!soundOn) return;
203:   try {
204:     audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
205:     const oscillator = audioContext.createOscillator();
206:     const gain = audioContext.createGain();
207:     oscillator.type = 'sine'; oscillator.frequency.value = frequency;
208:     gain.gain.setValueAtTime(.035, audioContext.currentTime);
209:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration);
210:     oscillator.connect(gain); gain.connect(audioContext.destination);
211:     oscillator.start(); oscillator.stop(audioContext.currentTime + duration);
212:   } catch (_) { /* Audio is an optional flourish. */ }
213: }
214: $('soundToggle').addEventListener('click', () => {
215:   soundOn = !soundOn;
216:   $('soundToggle').classList.toggle('enabled', soundOn);
217:   $('soundState').textContent = soundOn ? 'ON' : 'OFF';
218:   if (soundOn) playTone(580, .13);
219: });
220: let auctionTimerId = null, auctionBidId = null, auctionEndsAt = 0;
221: let auctionBid = 0, auctionCount = 0, lastBidder = -1;
222: const bidderNames = ['VEX-9', 'MASTER SOL', 'NYX KORR', 'DR. LUMA', 'JAX RENN', 'THE CURATOR'];
223: function stopAuction() {
224:   clearInterval(auctionTimerId); clearTimeout(auctionBidId);
225:   auctionTimerId = null; auctionBidId = null;
226: }
227: function closeSale() {
228:   stopAuction();
229:   $('saleOverlay').classList.remove('open'); $('saleOverlay').setAttribute('aria-hidden', 'true');
230:   document.body.classList.remove('sale-active');
231:   document.body.style.removeProperty('overflow');
232: }
233: function finishAuction() {
234:   if ($('auctionRoom').classList.contains('finished')) return;
235:   stopAuction();
236:   $('auctionRoom').classList.add('finished');
237:   $('auctionResult').classList.add('visible'); $('auctionResult').setAttribute('aria-hidden', 'false');
238:   $('salePrice').textContent = money(auctionBid);
239:   $('resultCopy').textContent = `${$('auctionBidder').textContent} takes home your ${buildName()} saber. The room made ${auctionCount} bids before the hammer fell.`;
240:   const base = Object.values(options).reduce((sum, list, index) => sum + selectedOption(Object.keys(options)[index]).price, 0);
241:   const bonus = totalValue() - base;
242:   const breakdown = Object.entries(options).map(([key]) => `<div><span>${steps.find(step => step.id === key).title}</span><b>${money(selectedOption(key).price)}</b></div>`);
243:   breakdown.push(`<div><span>Craftsmanship bonus</span><b>${money(bonus)}</b></div>`);
244:   breakdown.push(`<div><span>Auction premium</span><b>${money(auctionBid - totalValue())}</b></div>`);
245:   $('saleBreakdown').innerHTML = breakdown.join('');
246:   playTone(820, .24);
247: }
248: function placeBid() {
249:   if ($('auctionRoom').classList.contains('finished')) return;
250:   let bidderIndex = Math.floor(Math.random() * 6);
251:   if (bidderIndex === lastBidder) bidderIndex = (bidderIndex + 1 + Math.floor(Math.random() * 5)) % 6;
252:   lastBidder = bidderIndex;
253:   const increase = .045 + Math.random() * .075;
254:   auctionBid = Math.ceil((auctionBid * (1 + increase)) / 10) * 10;
255:   auctionCount++;
256:   const bidder = document.querySelector(`[data-bidder="${bidderIndex}"]`);
257:   bidder.classList.add('bidding');
258:   bidder.querySelector('.bid-tag').textContent = money(auctionBid);
259:   $('auctionPrice').textContent = money(auctionBid);
